const req = $("Read Request").first().json;
const items = $input.all().map(function (i) { return i.json; });
const EMAIL = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/;
const byHandle = {};
items.forEach(function (it) {
  const a = it.authorMeta || it.author || it.user || it;
  const raw = a.name || a.uniqueId || a.nickName || a.userName || a.handle || "";
  const handle = String(raw).replace(/^@/, "").trim();
  if (!handle) { return; }
  const key = handle.toLowerCase();
  const fRaw = a.fans != null ? a.fans : (a.followers != null ? a.followers : (a.followerCount != null ? a.followerCount : (a.stats && a.stats.followerCount)));
  const followers = Number(fRaw) || 0;
  const bRaw = a.signature != null ? a.signature : (a.bio != null ? a.bio : (a.desc != null ? a.desc : ""));
  const bio = String(bRaw).replace(/\s+/g, " ").trim();
  const hit = bio.match(EMAIL);
  const contact = hit ? hit[0].toLowerCase() : "";
  const prev = byHandle[key];
  const better = !prev || followers > prev.followers || (bio && !prev.bio);
  if (better) {
    byHandle[key] = { handle: handle, followers: followers, bio: bio, contact: contact, profileUrl: "https://www.tiktok.com/@" + handle };
  } else if (contact && !prev.contact) {
    prev.contact = contact;
  }
});
const profiles = Object.keys(byHandle).map(function (k) { return byHandle[k]; });
const withContact = profiles.filter(function (p) { return p.contact; }).length;
const out = { t0: req.t0, tScrape: Date.now(), keyword: req.keyword, minFollowers: req.minFollowers, maxResults: req.maxResults, rawItemCount: items.length, profiles: profiles, profileCount: profiles.length, withContact: withContact };
return [{ json: out }];

const p = $input.first().json;
const passed = p.profiles.filter(function (x) { return x.followers >= p.minFollowers; });
const extra = { tFilter: Date.now(), passed: passed, passedCount: passed.length, rejectedCount: p.profiles.length - passed.length };
return [{ json: Object.assign({}, p, extra) }];

const prev = $("Filter By Follower Count").first().json;
const RUBRIC = "You score TikTok creators on their fit for a paid partnership with ElevenLabs, an AI audio company. ElevenLabs makes text-to-speech, voice cloning, dubbing into 70+ languages, AI music, and voice agents. Their creator program wants people whose audience would plausibly use those tools. Score each creator 0-100 using this rubric. 85-100: already makes content about AI voice, TTS, dubbing, or AI content tooling. 70-84: creator economy, faceless content, video editing, voiceover, or audio production. 50-69: general AI, tech, or software audience, or heavily narration-driven content. 25-49: adjacent creative audience with no clear audio or AI hook. 0-24: no plausible connection. Judge only from the bio text and follower count given. Never invent facts about a creator. If a bio is empty or uninformative, score no higher than 30 and say the bio was thin. Return strict JSON with a single key called scores, whose value is an array of objects. Each object has three keys: handle (the exact handle from the input), score (integer 0-100), and reasoning (one sentence, max 22 words, naming the specific signal you used). Include every handle from the input exactly once. If the input creator list is empty, return an empty scores array.";
const existing = {};
let existingCount = 0;
$input.all().forEach(function (i) {
  const j = i.json || {};
  const f = j.fields || {};
  const h = j.Handle != null ? j.Handle : f.Handle;
  if (h) { existing[String(h).replace(/^@/, "").toLowerCase().trim()] = true; existingCount++; }
});
const fresh = prev.passed.filter(function (c) { return !existing[c.handle.toLowerCase().trim()]; });
const duplicatesBlocked = prev.passed.length - fresh.length;
const capped = fresh.slice(0, prev.maxResults);
const slim = capped.map(function (c) { return { handle: c.handle, followers: c.followers, bio: c.bio }; });
const userPayload = JSON.stringify({ keyword: prev.keyword, creators: slim });
const scoringPrompt = { system: RUBRIC, user: userPayload };
const extra = { tDedupe: Date.now(), existingCount: existingCount, newCreators: capped, newCount: capped.length, duplicatesBlocked: duplicatesBlocked, scoringPrompt: scoringPrompt };
return [{ json: Object.assign({}, prev, extra) }];

const d = $("Remove Duplicates").first().json;
const tScore = Date.now();
let scores = [];
let aiError = null;
function looksLikeScores(a) {
  return Array.isArray(a) && a.length > 0 && a[0] && typeof a[0] === "object" && a[0].handle !== undefined;
}
function findScores(n, depth) {
  if (n == null || depth > 8) { return null; }
  if (typeof n === "string") {
    const s = n.trim();
    if (s.charAt(0) !== "{" && s.charAt(0) !== "[") { return null; }
    try { return findScores(JSON.parse(s), depth + 1); } catch (e) { return null; }
  }
  if (Array.isArray(n)) {
    if (looksLikeScores(n)) { return n; }
    for (let i = 0; i < n.length; i++) {
      const r = findScores(n[i], depth + 1);
      if (r) { return r; }
    }
    return null;
  }
  if (typeof n === "object") {
    if (Array.isArray(n.scores)) { return n.scores; }
    const keys = ["text", "content", "output_text", "output", "message", "choices", "json", "response"];
    for (let i = 0; i < keys.length; i++) {
      if (n[keys[i]] !== undefined) {
        const r = findScores(n[keys[i]], depth + 1);
        if (r) { return r; }
      }
    }
    return null;
  }
  return null;
}
try {
  const found = findScores($input.first().json, 0);
  if (found === null) { throw new Error("no scores array found in model response"); }
  scores = found;
} catch (e) { aiError = String(e.message || e); scores = []; }
const byHandle = {};
scores.forEach(function (s) { if (s && s.handle) { byHandle[String(s.handle).replace(/^@/, "").toLowerCase().trim()] = s; } });
const creators = d.newCreators.map(function (c) {
  const s = byHandle[c.handle.toLowerCase().trim()];
  let score = null;
  const hasScore = s && s.score !== undefined && s.score !== null && !isNaN(Number(s.score));
  if (hasScore) { score = Math.max(0, Math.min(100, Math.round(Number(s.score)))); }
  const why = s && s.reasoning ? String(s.reasoning) : "Not scored.";
  return { handle: c.handle, followers: c.followers, bio: c.bio, contact: c.contact || "", profileUrl: c.profileUrl, score: score, reasoning: why };
});
creators.sort(function (a, b) { return (b.score === null ? -1 : b.score) - (a.score === null ? -1 : a.score); });
const scored = creators.filter(function (c) { return c.score !== null; });
const withContact = creators.filter(function (c) { return c.contact; }).length;
const avgScore = scored.length ? Math.round(scored.reduce(function (t, c) { return t + c.score; }, 0) / scored.length) : null;
const ms = function (a, b) { return Math.max(0, Math.round(b - a)); };
const minLabel = Number(d.minFollowers).toLocaleString("en-US");
const dupeNote = d.duplicatesBlocked ? (" (" + d.duplicatesBlocked + " blocked)") : "";
const aiDetail = aiError ? ("scoring failed: " + aiError) : (scored.length + "/" + creators.length + " scored");
const writeDetail = creators.length + " records created" + (withContact ? (", " + withContact + " with contact") : "");
const stages = [];
stages.push({ name: "Kill switch", detail: "clear", status: "ok" });
stages.push({ name: "Apify TikTok scrape", detail: d.rawItemCount + " posts, " + d.profileCount + " unique profiles", ms: ms(d.t0, d.tScrape), status: "ok" });
stages.push({ name: "Follower filter (min " + minLabel + ")", detail: d.profileCount + " to " + d.passedCount, ms: ms(d.tScrape, d.tFilter), status: "ok" });
stages.push({ name: "Dedupe against Airtable", detail: d.passedCount + " to " + d.newCount + dupeNote, ms: ms(d.tFilter, d.tDedupe), status: "ok" });
stages.push({ name: "AI brand-fit scoring", detail: aiDetail, ms: ms(d.tDedupe, tScore), status: aiError ? "failed" : "ok" });
stages.push({ name: "Airtable write", detail: writeDetail, status: creators.length ? "ok" : "skipped" });
const summary = { scanned: d.profileCount, passedFilter: d.passedCount, newCreators: creators.length, duplicatesBlocked: d.duplicatesBlocked, withContact: withContact, avgScore: avgScore };
const out = { halted: false, keyword: d.keyword, summary: summary, stages: stages, creators: creators };
return [{ json: out }];

const kw = $("Read Request").first().json.keyword;
const names = ["Kill switch", "Apify TikTok scrape", "Follower filter", "Dedupe against Airtable", "AI brand-fit scoring", "Airtable write"];
const stages = names.map(function (n, i) {
  const detail = i === 0 ? "enabled in Airtable - run halted" : "not run";
  return { name: n, detail: detail, status: "skipped" };
});
const out = { halted: true, keyword: kw, stages: stages, creators: [] };
return [{ json: out }];

const d = $("Build Result").first().json;
const rows = d.creators || [];
return rows.map(function (c) {
  const r = {};
  r.Handle = c.handle;
  r["Profile URL"] = c.profileUrl;
  r.Followers = c.followers;
  r.Bio = c.bio;
  r["Fit Score"] = c.score;
  r["Score Reasoning"] = c.reasoning;
  r["Discovered At"] = new Date().toISOString();
  if (c.contact) { r.Contact = c.contact; }
  return { json: r };
});

